class Solution { fun possibleToStamp(grid:Array<IntArray>,stampHeight:Int,stampWidth:Int):Boolean{val rows=grid.size;val columns=grid[0].size;val prefix=Array(rows+1){IntArray(columns+1)};val cover=Array(rows+1){IntArray(columns+1)};for(r in 0 until rows)for(c in 0 until columns)prefix[r+1][c+1]=grid[r][c]+prefix[r][c+1]+prefix[r+1][c]-prefix[r][c];for(r in 0..rows-stampHeight)for(c in 0..columns-stampWidth){val bottom=r+stampHeight;val right=c+stampWidth;val occupied=prefix[bottom][right]-prefix[r][right]-prefix[bottom][c]+prefix[r][c];if(occupied==0){cover[r][c]++;cover[bottom][c]--;cover[r][right]--;cover[bottom][right]++}};for(r in 0 until rows)for(c in 0 until columns){if(r>0)cover[r][c]+=cover[r-1][c];if(c>0)cover[r][c]+=cover[r][c-1];if(r>0&&c>0)cover[r][c]-=cover[r-1][c-1];if(grid[r][c]==0&&cover[r][c]==0)return false};return true} }
